}
# Additional high precision title/source hints
source_hints={
    'Sports': [r'\(sports network\)', r'\bap sports\b', r'\bnba wrap\b', r'\bnfl roundup\b'],
    'Science/Technology': [r'\(space\.com\)', r'\(pc world\)', r'\(infoworld\)', r'\(zdnet\)', r'\(newsfactor\)', r'\(washingtonpost\.com\).*technology'],
}
