import re, math, sqlite3, html, heapq
from collections import Counter
from pymongo import MongoClient
col=MongoClient('mongodb://dab-mongo:27017')['articles_db']['articles']
articles={d['article_id']:(d['title'], d['description']) for d in col.find({}, {'_id':0,'article_id':1,'title':1,'description':1})}
conn=sqlite3.connect('file:/workspace/query_dataset/metadata.db?mode=ro', uri=True)
cur=conn.cursor(); meta={r[0]:(r[1],r[2],r[3]) for r in cur.execute('select article_id, author_id, region, publication_date from article_metadata')}
amy_id=cur.execute("select author_id from authors where name='Amy Jones'").fetchone()[0]
amy=[r[0] for r in cur.execute('select article_id from article_metadata where author_id=? order by article_id',(amy_id,))]
q3=[aid for aid,(a,r,d) in meta.items() if r=='Europe' and 2010<=int(d[:4])<=2020]
q4=[aid for aid,(a,r,d) in meta.items() if d[:4]=='2015']
q1=[aid for _,aid in heapq.nlargest(500, [(len(d),aid) for aid,(t,d) in articles.items()])]
target=set(amy)|set(q3)|set(q4)|set(q1)
cat_names=['World','Sports','Business','Science/Technology']
def norm(s):
    s=html.unescape(s or '').replace('\\',' ')
    s=re.sub(r'<[^>]+>',' ',s); s=re.sub(r'#[0-9]+;',' ',s)
    s=re.sub(r'[^a-zA-Z0-9$]+',' ',s.lower())
    return re.sub(r'\s+',' ',s).strip()
texts={aid:norm(t+' '+t+' '+d) for aid,(t,d) in articles.items()}
# High precision regexes only
seed_patterns={
'Sports':[r'\b(nfl|nba|mlb|nhl|ncaa|uefa|fifa|olympics?|soccer|football|baseball|basketball|tennis|golf|cricket|rugby|hockey|cycling|boxing|nascar|formula one|grand prix|world cup|champions league|quarterback|touchdown|pitcher|yankees|red sox|dodgers|lakers|arsenal|liverpool|manchester|real madrid|patriots|packers|rams|rockets|capriati|serena|federer|agassi|sorenstam|schumacher|montoya)\b'],
'Business':[r'\b(stocks?|shares?|wall street|nasdaq|dow|earnings|profit|profits|revenue|ipo|investors?|bankruptcy|merger|acquisition|buyout|ceo|corp|inc|ltd|company|oil prices?|crude prices?|opec|economy|economic|wto|federal reserve|inflation|jobless|producer prices|consumer prices|quarter profit|quarter earnings|sec|nyse|mortgage|insurance|retailer|airline)\b'],
'Science/Technology':[r'\b(software|hardware|internet|web|online|computer|pc|server|linux|windows|microsoft|google|yahoo|apple|ibm|intel|amd|oracle|cisco|nokia|motorola|samsung|ebay|paypal|itunes|rfid|wireless|broadband|semiconductor|chip|processor|virus|spam|hacker|cyber|database|open source|browser|search engine|digital|gameboy|video game|xbox|playstation|space|nasa|spacecraft|satellite|mars|planet|comet|asteroid|astronomers?|scientists?|researchers?|biotech|genome|shuttle|rocket|physics|science)\b'],
'World':[r'\b(iraq|iran|israel|palestinian|gaza|afghanistan|sudan|darfur|kashmir|russia|ukraine|north korea|china|japan|france|germany|britain|european union|united nations|nato|prime minister|president|government|parliament|election|kerry|bush|blair|putin|chavez|karzai|war|military|troops|soldiers|insurgents?|militants?|rebels?|terrorism?|bomb|blast|killed|dead|attack|peace|diplomat|summit|police|protest|refugee|hostage|nuclear)\b']
}
comp={c:[re.compile(p) for p in ps] for c,ps in seed_patterns.items()}
def seed_score(s):
    sc={c:0 for c in cat_names}
    for c,ps in comp.items():
        for p in ps: sc[c]+=len(p.findall(s))
    # source boosts
    if 'sports network' in s or 'nba wrap' in s or 'nfl roundup' in s: sc['Sports']+=5
    if 'space com' in s or 'infoworld' in s or 'pc world' in s or 'newsfactor' in s: sc['Science/Technology']+=5
    return sc

def toks(s):
    base=[x for x in s.split() if len(x)>1 and not x.isdigit()]
    # remove ultra generic words that were harming category boundaries
    stop=set('the and for with that this from are was were its has have but into over after before says said more will new not his her who what when where why how out about than their been can all one two you your our they them week year years today yesterday'.split())
    base=[x for x in base if x not in stop]
    return base+[base[i]+'_'+base[i+1] for i in range(len(base)-1)]
seed=[]
for aid,s in texts.items():
    sc=seed_score(s); order=sorted(sc.items(), key=lambda kv:kv[1], reverse=True)
    if order[0][1]>=2 and order[0][1]>=order[1][1]+2: seed.append((aid,order[0][0]))
print('seed2', len(seed), Counter(c for _,c in seed))
raw=Counter(); ct={c:Counter() for c in cat_names}; cd=Counter()
for aid,c in seed:
    ts=toks(texts[aid]); raw.update(ts); ct[c].update(ts); cd[c]+=1
vocab=set(w for w,n in raw.most_common(50000) if n>=2); V=len(vocab); alpha=.5; N=sum(cd.values())
# feature weighting by log odds? use NB
cat_total={c:sum(n for w,n in ct[c].items() if w in vocab) for c in cat_names}
def predict(aid):
    cnt=Counter(w for w in toks(texts[aid]) if w in vocab); logs={}
    for c in cat_names:
        denom=cat_total[c]+alpha*V; lp=math.log((cd[c]+1)/(N+len(cat_names)))
        cc=ct[c]
        for w,n in cnt.items(): lp+=n*math.log((cc[w]+alpha)/denom)
        logs[c]=lp
    o=sorted(logs.items(), key=lambda kv:kv[1], reverse=True)
    return o[0][0], o[0][1]-o[1][1], logs, seed_score(texts[aid])
pred={a:predict(a)[0] for a in target}
print('target counts', Counter(pred.values()))
print('q1 sports top', [(a,len(articles[a][1]),articles[a][0]) for a in sorted([a for a in q1 if pred[a]=='Sports'], key=lambda a:(-len(articles[a][1]),a))[:10]])
print('q2', len(amy), Counter(pred[a] for a in amy), sum(pred[a]=='Science/Technology' for a in amy), [a for a in amy if pred[a]=='Science/Technology'])
print('q3', sum(pred[a]=='Business' for a in q3), sum(pred[a]=='Business' for a in q3)/11, sorted(Counter(int(meta[a][2][:4]) for a in q3 if pred[a]=='Business').items()))
q4c=Counter(meta[a][1] for a in q4 if pred[a]=='World')
print('q4', q4c, q4c.most_common())
# strong seed world q4 only
seedworld=Counter(); seedall=Counter(); unresolved=0
for a in q4:
    sc=seed_score(texts[a]); order=sorted(sc.items(), key=lambda kv:kv[1], reverse=True)
    if order[0][1]>=2 and order[0][1]>=order[1][1]+2:
        seedall[order[0][0]]+=1
        if order[0][0]=='World': seedworld[meta[a][1]]+=1
    else: unresolved+=1
print('q4 strong seed world', seedworld, seedworld.most_common(), 'seedall', seedall, 'unresolved', unresolved)
